    end_def = json.load(f)['Data']['Node']
with open('/tmp/script_def.json') as f:
    script_def = json.load(f)['Data']['Node']

# Load current flow to preserve IDs
with open('TransformMapDemo.flow') as f:
    flow = json.load(f)

# Existing manual trigger definition
manual_def = flow['definitions'][0]

